import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'motion/react';
import {
  Award, Download, CheckCircle, Clock, XCircle,
  Upload, Loader2, AlertCircle, Plus,
  Search, X, RefreshCw
} from 'lucide-react';
import jsPDF from 'jspdf';
import { supabase } from '../lib/supabase';

// Certificate background template (embedded)
const CERT_BG = "";

interface Certificate {
  id: string;
  event_id: string;
  event_name?: string;
  sub_event_id?: string;
  sub_event_name?: string;
  participant_name: string;
  participant_designation?: string;
  participant_organization?: string;
  district?: string;
  certificate_date: string;
  event_date?: string;
  venue?: string;
  issued_by?: string;
  issued_by_id?: string;
  signature_url?: string;
  status: string;
  approved_by?: string;
  approved_by_id?: string;
  approved_at?: string;
  created_at: string;
}

const isSuperOrState = (s: any) => ['SUPER_ADMIN', 'STATE_ADMIN'].includes(s?.role);
const isDistrictAdmin = (s: any) => s?.role === 'DISTRICT_ADMIN';
const isAdmin = (s: any) => isSuperOrState(s) || isDistrictAdmin(s);

function fmtDateEn(d?: string) {
  if (!d) return '';
  return new Date(d).toLocaleDateString('en-IN', { day: '2-digit', month: 'long', year: 'numeric' });
}

// Remove white/light background from signature image
async function removeWhiteBackground(file: File): Promise<Blob> {
  return new Promise((resolve) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d')!;
      ctx.drawImage(img, 0, 0);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imageData.data;
      for (let i = 0; i < data.length; i += 4) {
        const r = data[i], g = data[i + 1], b = data[i + 2], a = data[i + 3];
        // Calculate luminance (standard grayscaling)
        const luma = 0.299 * r + 0.587 * g + 0.114 * b;
        
        if (luma > 150) {
          // Smooth fade out of any paper background
          const alpha = luma >= 220 ? 0 : Math.round(((220 - luma) / 70) * 255);
          data[i + 3] = Math.min(alpha, a);
          
          // Color-normalize semi-transparent pixels towards dark to prevent a white halo outline
          const inkFactor = Math.min(1, Math.max(0, (luma - 150) / 70));
          data[i] = Math.round(r * (1 - inkFactor));
          data[i + 1] = Math.round(g * (1 - inkFactor));
          data[i + 2] = Math.round(b * (1 - inkFactor));
        } else {
          // Solidify and boost contrast of the ink line
          data[i] = Math.round(r * 0.7);
          data[i + 1] = Math.round(g * 0.7);
          data[i + 2] = Math.round(b * 0.7);
        }
      }
      ctx.putImageData(imageData, 0, 0);
      URL.revokeObjectURL(url);
      canvas.toBlob(blob => resolve(blob!), 'image/png');
    };
    img.src = url;
  });
}

function statusColor(s: string) {
  if (s === 'approved') return 'bg-green-100 text-green-700 border-green-200';
  if (s === 'rejected') return 'bg-red-100 text-red-700 border-red-200';
  return 'bg-amber-100 text-amber-700 border-amber-200';
}

async function generateCertificatePDF(cert: Certificate, signatureUrl?: string) {
  const pdf = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const W = 297, H = 210;

  const toBase64 = async (url: string): Promise<string | null> => {
    try {
      const res = await fetch(url);
      const blob = await res.blob();
      return new Promise(resolve => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => resolve(null);
        reader.readAsDataURL(blob);
      });
    } catch { return null; }
  };

  // Background blank template
  pdf.addImage(`data:image/jpeg;base64,${CERT_BG}`, 'JPEG', 0, 0, W, H);

  const certNum = `UK-AYUSH-CERT-${new Date(cert.certificate_date).getFullYear()}-${cert.id.slice(0, 6).toUpperCase()}`;

  // S.N. top
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(11);
  pdf.setTextColor(30, 30, 30);
  pdf.text(`S.N.:- ${certNum}`, 148.5, 9);

  // Name + Designation — center aligned on right half
  let nameLine = cert.participant_name;
  if (cert.participant_designation) nameLine += `, ${cert.participant_designation}`;
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(14);
  pdf.setTextColor(20, 20, 80);
  pdf.text(nameLine, 201, 85, { align: 'center' });

  // Organisation
  if (cert.participant_organization) {
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(14);
    pdf.setTextColor(60, 60, 60);
    pdf.text(cert.participant_organization!, 201, 94, { align: 'center' });
  }

  // Recognition paragraph
  const hasSubEvent = cert.sub_event_id && cert.sub_event_name;
  const eventDate = fmtDateEn(cert.event_date || cert.certificate_date);
  const venue = cert.venue || '';

  const renderMixed = (parts: {t: string, b: boolean}[], x: number, y: number) => {
    // Calculate total width first to center
    let totalWidth = 0;
    parts.forEach(p => {
       pdf.setFont('helvetica', p.b ? 'bold' : 'normal');
       pdf.setFontSize(14);
       totalWidth += pdf.getTextWidth(p.t);
    });

    let currentX = x - (totalWidth / 2);
    parts.forEach(p => {
      pdf.setFont('helvetica', p.b ? 'bold' : 'normal');
      pdf.setFontSize(14);
      pdf.text(p.t, currentX, y);
      currentX += pdf.getTextWidth(p.t);
    });
  };

  const splitTextToLines = (text: string, maxWidth: number): string[] => {
    const words = text.split(/\s+/);
    const lines: string[] = [];
    let currentLine = '';
    for (const word of words) {
      const testLine = currentLine ? `${currentLine} ${word}` : word;
      pdf.setFont('helvetica', 'bold');
      pdf.setFontSize(14);
      const width = pdf.getTextWidth(testLine);
      if (width > maxWidth) {
        if (currentLine) {
          lines.push(currentLine);
          currentLine = word;
        } else {
          lines.push(word);
          currentLine = '';
        }
      } else {
        currentLine = testLine;
      }
    }
    if (currentLine) {
      lines.push(currentLine);
    }
    return lines;
  };

  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(14);
  pdf.setTextColor(40, 40, 40);
  pdf.text('In recognition of his/her active participation during', 201, 100, { align: 'center' });

  let currentY = 107;

  if (hasSubEvent) {
    // Split into elegant multiple lines to prevent overlapping the left teal circle and bounds
    const subEventText = `${cert.sub_event_name!} Activity`;
    const subEventLines = splitTextToLines(subEventText, 140);
    subEventLines.forEach(line => {
      renderMixed([{t: line, b: true}], 201, currentY);
      currentY += 7.5;
    });

    // Organised Under Event Name (wrapped dynamically)
    const orgUnderText = `organised under ${cert.event_name!}`;
    const orgUnderLines = splitTextToLines(orgUnderText, 140);
    orgUnderLines.forEach(line => {
      if (line.startsWith('organised under ')) {
        const rest = line.substring('organised under '.length);
        renderMixed([
          {t: 'organised under ', b: false},
          {t: rest, b: true}
        ], 201, currentY);
      } else {
        renderMixed([{t: line, b: true}], 201, currentY);
      }
      currentY += 7.5;
    });

    // Date and Venue
    renderMixed([
      {t: 'on ', b: false},
      {t: eventDate, b: true}
    ], 201, currentY);
    currentY += 7.5;

    renderMixed([
      {t: 'at ', b: false},
      {t: `${venue}.`, b: true}
    ], 201, currentY);
    currentY += 10;
  } else {
    // Event Name (wrapped dynamically)
    const eventLines = splitTextToLines(cert.event_name!, 140);
    eventLines.forEach(line => {
      renderMixed([{t: line, b: true}], 201, currentY);
      currentY += 7.5;
    });

    // Date and Venue
    renderMixed([
      {t: 'on ', b: false},
      {t: eventDate, b: true}
    ], 201, currentY);
    currentY += 7.5;

    renderMixed([
      {t: 'at ', b: false},
      {t: `${venue}.`, b: true}
    ], 201, currentY);
    currentY += 10;
  }

  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(14);
  pdf.setTextColor(40, 40, 40);
  pdf.text('Your significant contribution in promoting Yoga is highly appreciated.', 201, currentY, { align: 'center' });
  currentY += 8.5;
  pdf.text('We expect your similar contribution in future events', 201, currentY, { align: 'center' });
  currentY += 7.5;
  pdf.text('for propagating Yoga in state.', 201, currentY, { align: 'center' });

  // Footer
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(13);
  pdf.setTextColor(30, 30, 30);
  pdf.text(`Date: ${fmtDateEn(cert.certificate_date)}`, 105, 196);

  if (signatureUrl) {
    const sigB64 = await toBase64(signatureUrl);
    if (sigB64) pdf.addImage(sigB64, 'PNG', 243, 182, 35, 12);
  }
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(13);
  pdf.text('Signatory', 261, 196);
  if (cert.approved_by) {
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(9);
    pdf.text(cert.approved_by, 261, 201);
  }

  pdf.save(`Certificate_${cert.participant_name.replace(/\s+/g, '_')}_${certNum}.pdf`);
}

function RequestCertificateModal({ session, events, subEvents, onClose, onDone }: any) {
  const [form, setForm] = useState({
    event_id: '', sub_event_id: '', participant_name: '',
    participant_designation: '', participant_organization: '',
    event_date: '', venue: '',
  });
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');

  const selectedEventSubEvents = subEvents.filter((s: any) => s.event_id === form.event_id);

  const handleSave = async () => {
    if (!form.event_id) { setError('Event select karo'); return; }
    if (!form.participant_name.trim()) { setError('Participant naam zaroori hai'); return; }
    if (!form.event_date) { setError('Event date zaroori hai'); return; }
    const todayStr = new Date().toISOString().split('T')[0];
    if (form.event_date > todayStr) {
      setError('Event date cannot be in the future.');
      return;
    }
    if (!form.venue.trim()) { setError('Venue zaroori hai'); return; }
    setSaving(true);
    try {
      const selectedEvent = events.find((e: any) => e.id === form.event_id);
      const selectedSub = subEvents.find((s: any) => s.id === form.sub_event_id);
      let district = session?.district || session?.present_district || null;
      if (!district && session?.id) {
        const { data: sd } = await supabase.from('staff').select('present_district').eq('id', session.id).maybeSingle();
        if (sd?.present_district) district = sd.present_district;
      }
      if (!district && session?.id) {
        const { data: ad } = await supabase.from('admin_logins').select('access_districts').eq('id', session.id).maybeSingle();
        if (ad?.access_districts?.[0]) district = ad.access_districts[0];
      }
      const { error: err } = await supabase.from('certificates').insert({
        event_id: form.event_id, event_name: selectedEvent?.title,
        sub_event_id: form.sub_event_id || null, sub_event_name: selectedSub?.title || null,
        participant_name: form.participant_name.trim(),
        participant_designation: form.participant_designation.trim() || null,
        participant_organization: form.participant_organization.trim() || null,
        event_date: form.event_date, venue: form.venue.trim(),
        certificate_date: new Date().toISOString().split('T')[0],
        issued_by: session?.name || session?.id, issued_by_id: session?.id,
        issuer_role: session?.role, district, status: 'pending',
      });
      if (err) throw err;
      onDone();
    } catch (err: any) { setError(err.message); }
    finally { setSaving(false); }
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <motion.div initial={{ scale: 0.95, y: 20 }} animate={{ scale: 1, y: 0 }}
        className="bg-white rounded-3xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
        <div className="bg-gradient-to-r from-teal-700 to-teal-600 px-6 py-5 flex items-center justify-between rounded-t-3xl">
          <div>
            <h2 className="text-white font-bold text-lg">Certificate Request</h2>
            <p className="text-teal-200 text-xs">Participation Certificate</p>
          </div>
          <button onClick={onClose} className="text-teal-200 hover:text-white"><X size={20} /></button>
        </div>
        <div className="p-6 space-y-4">
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-xl p-3 text-sm text-red-700 flex items-center gap-2">
              <AlertCircle size={14} />{error}
            </div>
          )}
          <div>
            <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Event *</label>
            <select value={form.event_id} onChange={e => setForm(f => ({ ...f, event_id: e.target.value, sub_event_id: '' }))}
              className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20">
              <option value="">Select Event</option>
              {events.map((ev: any) => <option key={ev.id} value={ev.id}>{ev.title}</option>)}
            </select>
          </div>
          {selectedEventSubEvents.length > 0 && (
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Sub Event (Optional)</label>
              <select value={form.sub_event_id} onChange={e => setForm(f => ({ ...f, sub_event_id: e.target.value }))}
                className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20">
                <option value="">Event only</option>
                {selectedEventSubEvents.map((s: any) => <option key={s.id} value={s.id}>{s.title}</option>)}
              </select>
            </div>
          )}
          <div>
            <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Participant Name *</label>
            <input type="text" value={form.participant_name}
              onChange={e => setForm(f => ({ ...f, participant_name: e.target.value }))}
              placeholder="Full name"
              className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Designation</label>
              <input type="text" value={form.participant_designation}
                onChange={e => setForm(f => ({ ...f, participant_designation: e.target.value }))}
                placeholder="Medical Officer"
                className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20" />
            </div>
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Organisation</label>
              <input type="text" value={form.participant_organization}
                onChange={e => setForm(f => ({ ...f, participant_organization: e.target.value }))}
                placeholder="AYUSH Department"
                className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20" />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Event Date *</label>
              <input type="date" value={form.event_date}
                onChange={e => setForm(f => ({ ...f, event_date: e.target.value }))}
                max={new Date().toISOString().split('T')[0]}
                className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20" />
            </div>
            <div>
              <label className="text-xs font-bold uppercase tracking-wider text-slate-400 block mb-1.5">Venue *</label>
              <input type="text" value={form.venue}
                onChange={e => setForm(f => ({ ...f, venue: e.target.value }))}
                placeholder="Venue name"
                className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500/20" />
            </div>
          </div>
          <div className="bg-teal-50 border border-teal-200 rounded-xl p-3 flex items-center gap-2">
            <CheckCircle size={14} className="text-teal-600" />
            <p className="text-teal-700 text-xs font-medium">Certificate will be issued on current date.</p>
          </div>
          <button onClick={handleSave} disabled={saving}
            className="w-full flex items-center justify-center gap-2 py-3.5 bg-teal-600 text-white rounded-2xl font-bold hover:bg-teal-700 transition-colors disabled:opacity-50">
            {saving ? <><Loader2 size={16} className="animate-spin" />Saving...</> : <><Award size={16} />Submit Request</>}
          </button>
        </div>
      </motion.div>
    </motion.div>
  );
}

export default function EventCertificate({ session, events, subEvents }: {
  session: any; events: any[]; subEvents: any[];
}) {
  const [certificates, setCertificates] = useState<Certificate[]>([]);
  const [loading, setLoading] = useState(true);
  const [showRequestModal, setShowRequestModal] = useState(false);
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDistrict, setFilterDistrict] = useState('all');
  const [searchName, setSearchName] = useState('');
  const [mySignature, setMySignature] = useState('');
  const [uploadingSign, setUploadingSign] = useState(false);
  const [downloading, setDownloading] = useState<string | null>(null);
  const [processing, setProcessing] = useState<string | null>(null);
  const [toast, setToast] = useState('');
  const signatureRef = useRef<HTMLInputElement>(null);

  const showToast = (msg: string) => { setToast(msg); setTimeout(() => setToast(''), 3000); };

  const fetchCertificates = useCallback(async () => {
    setLoading(true);
    let query = supabase.from('certificates').select('*').order('created_at', { ascending: false });
    if (isDistrictAdmin(session)) {
      let dist = session?.district || session?.present_district;
      if (!dist) {
        const { data: ad } = await supabase.from('admin_logins').select('access_districts').eq('id', session?.id).maybeSingle();
        dist = ad?.access_districts?.[0];
      }
      if (dist) query = query.eq('district', dist);
    }
    if (filterStatus !== 'all') query = query.eq('status', filterStatus);
    if (filterDistrict !== 'all') query = query.eq('district', filterDistrict);
    const { data } = await query;
    let certs = data || [];
    if (searchName.trim()) certs = certs.filter((c: any) => c.participant_name.toLowerCase().includes(searchName.toLowerCase()));
    if (!isAdmin(session)) certs = certs.filter((c: any) => c.issued_by_id === session?.id);
    setCertificates(certs);
    setLoading(false);
  }, [session, filterStatus, filterDistrict, searchName]);

  useEffect(() => { fetchCertificates(); }, [fetchCertificates]);

  useEffect(() => {
    if (!isAdmin(session)) return;
    supabase.from('admin_signatures').select('signature_url').eq('admin_id', session?.id).maybeSingle()
      .then(({ data }) => { if (data?.signature_url) setMySignature(data.signature_url); });
  }, [session]);

  const handleUploadSignature = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploadingSign(true);
    try {
      // Remove white background from signature
      const processedBlob = await removeWhiteBackground(file);
      const path = `signatures/${session?.id}_${Date.now()}.png`;
      await supabase.storage.from('staff-photos').upload(path, processedBlob, { upsert: true, contentType: 'image/png' });
      const { data: urlData } = supabase.storage.from('staff-photos').getPublicUrl(path);
      const url = urlData.publicUrl;
      const { data: existing } = await supabase.from('admin_signatures').select('id').eq('admin_id', session?.id).maybeSingle();
      if (existing) {
        await supabase.from('admin_signatures').update({ signature_url: url, uploaded_at: new Date().toISOString() }).eq('admin_id', session?.id);
      } else {
        await supabase.from('admin_signatures').insert({ admin_id: session?.id, admin_name: session?.name, admin_role: session?.role, district: session?.district, signature_url: url });
      }
      setMySignature(url);
      showToast('✅ Signature uploaded!');
    } catch (err: any) { showToast('❌ ' + err.message); }
    finally { setUploadingSign(false); }
  };

  const handleApprove = async (cert: Certificate) => {
    if (!mySignature) { showToast('❌ Upload signature first!'); return; }
    setProcessing(cert.id);
    try {
      await supabase.from('certificates').update({
        status: 'approved', approved_by: session?.name,
        approved_by_id: session?.id, approved_at: new Date().toISOString(),
        signature_url: mySignature,
      }).eq('id', cert.id);
      showToast('✅ Certificate approved!');
      fetchCertificates();
    } catch (err: any) { showToast('❌ ' + err.message); }
    finally { setProcessing(null); }
  };

  const handleReject = async (cert: Certificate) => {
    setProcessing(cert.id);
    try {
      await supabase.from('certificates').update({ status: 'rejected' }).eq('id', cert.id);
      showToast('Rejected.');
      fetchCertificates();
    } catch (err: any) { showToast('❌ ' + err.message); }
    finally { setProcessing(null); }
  };

  const handleDownload = async (cert: Certificate) => {
    setDownloading(cert.id);
    try {
      await generateCertificatePDF(cert, cert.signature_url);
      showToast('✅ Certificate downloaded!');
    } catch (err: any) { showToast('❌ ' + err.message); }
    finally { setDownloading(null); }
  };

  const districts = [...new Set(certificates.map((c: any) => c.district).filter(Boolean))].sort() as string[];
  const canDownload = (cert: Certificate) => cert.status === 'approved' && (isAdmin(session) || cert.issued_by_id === session?.id);

  return (
    <div className="space-y-5">
      {isAdmin(session) && (
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-5">
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div>
              <h3 className="font-bold text-slate-800">Authorized Signature</h3>
              <p className="text-slate-400 text-xs mt-0.5">Will appear on all approved certificates</p>
              <p className="text-rose-600 font-bold text-xs mt-1.5">Please upload signature with transparent background in PNG format</p>
            </div>
            <div className="flex items-center gap-3">
              {mySignature && (
                <div className="border border-slate-200 rounded-xl p-2 bg-slate-50">
                  <img src={mySignature} alt="Signature" className="h-10 object-contain" />
                </div>
              )}
              <button onClick={() => signatureRef.current?.click()} disabled={uploadingSign}
                className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2.5 rounded-xl font-semibold text-sm hover:bg-teal-700 transition-colors disabled:opacity-50">
                {uploadingSign ? <><Loader2 size={15} className="animate-spin" />Uploading...</> : <><Upload size={15} />{mySignature ? 'Update Signature' : 'Upload Signature'}</>}
              </button>
              <input ref={signatureRef} type="file" accept="image/*" className="hidden" onChange={handleUploadSignature} />
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-2">
          <Award size={20} className="text-teal-600" />
          <h2 className="font-bold text-slate-800">Certificates</h2>
          <span className="text-xs bg-teal-100 text-teal-700 px-2 py-0.5 rounded-full font-bold">{certificates.length}</span>
        </div>
        <button onClick={() => setShowRequestModal(true)}
          className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2.5 rounded-xl font-bold text-sm hover:bg-teal-700 transition-colors shadow-md shadow-teal-200">
          <Plus size={15} />New Certificate
        </button>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 p-4 shadow-sm">
        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex gap-1.5">
            {['all','pending','approved','rejected'].map(s => (
              <button key={s} onClick={() => setFilterStatus(s)}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold capitalize transition-all ${filterStatus === s ? 'bg-teal-600 text-white' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}>
                {s}
              </button>
            ))}
          </div>
          {isSuperOrState(session) && districts.length > 0 && (
            <select value={filterDistrict} onChange={e => setFilterDistrict(e.target.value)}
              className="border border-slate-200 rounded-xl px-3 py-1.5 text-xs focus:outline-none">
              <option value="all">All Districts</option>
              {districts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          )}
          <div className="flex items-center gap-2 ml-auto bg-slate-50 border border-slate-200 rounded-xl px-3 py-1.5">
            <Search size={13} className="text-slate-400" />
            <input type="text" value={searchName} onChange={e => setSearchName(e.target.value)}
              placeholder="Search name..."
              className="bg-transparent text-xs focus:outline-none w-32" />
          </div>
          <button onClick={fetchCertificates} className="p-2 text-slate-400 hover:text-slate-600 rounded-xl transition-colors">
            <RefreshCw size={14} />
          </button>
        </div>
      </div>

      {loading ? (
        <div className="flex justify-center py-16"><Loader2 size={24} className="animate-spin text-teal-500" /></div>
      ) : certificates.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-2xl border border-dashed border-slate-200">
          <Award size={36} className="text-slate-200 mx-auto mb-3" />
          <p className="text-slate-400">No certificates found</p>
          <button onClick={() => setShowRequestModal(true)} className="mt-3 text-teal-600 text-sm font-semibold hover:underline">+ New Certificate</button>
        </div>
      ) : (
        <div className="space-y-3">
          {certificates.map((cert: Certificate) => (
            <div key={cert.id} className="bg-white rounded-2xl border border-slate-200 shadow-sm p-4">
              <div className="flex items-start gap-4">
                <div className="w-10 h-10 bg-teal-100 rounded-xl flex items-center justify-center flex-shrink-0">
                  <Award size={18} className="text-teal-600" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-slate-800">{cert.participant_name}
                    {cert.participant_designation && <span className="font-normal text-slate-500 text-sm">, {cert.participant_designation}</span>}
                  </p>
                  <p className="text-xs text-slate-500 mt-0.5">
                    {cert.event_name}{cert.sub_event_name && <span className="text-purple-600"> › {cert.sub_event_name}</span>}
                  </p>
                  <p className="text-xs text-slate-400 mt-0.5">
                    {cert.district && <span>{cert.district} • </span>}
                    {cert.venue && <span>{cert.venue} • </span>}
                    {fmtDateEn(cert.event_date || cert.certificate_date)}
                    {cert.issued_by && <span> • by {cert.issued_by}</span>}
                  </p>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0 flex-wrap justify-end">
                  <span className={`flex items-center gap-1 text-xs px-2.5 py-1 rounded-full border font-semibold ${statusColor(cert.status)}`}>
                    {cert.status === 'approved' ? <CheckCircle size={11} /> : cert.status === 'rejected' ? <XCircle size={11} /> : <Clock size={11} />}
                    {cert.status}
                  </span>
                  {canDownload(cert) && (
                    <button onClick={() => handleDownload(cert)} disabled={downloading === cert.id}
                      className="flex items-center gap-1.5 text-xs bg-teal-600 text-white px-3 py-2 rounded-xl font-bold hover:bg-teal-700 transition-colors disabled:opacity-50">
                      {downloading === cert.id ? <Loader2 size={13} className="animate-spin" /> : <Download size={13} />}PDF
                    </button>
                  )}
                  {isAdmin(session) && cert.status === 'pending' && (
                    <>
                      <button onClick={() => handleApprove(cert)} disabled={processing === cert.id || !mySignature}
                        title={!mySignature ? 'Upload signature first' : ''}
                        className="flex items-center gap-1.5 text-xs bg-green-600 text-white px-3 py-2 rounded-xl font-bold hover:bg-green-700 transition-colors disabled:opacity-50">
                        {processing === cert.id ? <Loader2 size={13} className="animate-spin" /> : <CheckCircle size={13} />}Approve
                      </button>
                      <button onClick={() => handleReject(cert)} disabled={processing === cert.id}
                        className="flex items-center gap-1.5 text-xs border border-red-300 text-red-600 px-3 py-2 rounded-xl font-bold hover:bg-red-50 transition-colors disabled:opacity-50">
                        <XCircle size={13} />Reject
                      </button>
                    </>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <AnimatePresence>
        {showRequestModal && (
          <RequestCertificateModal session={session} events={events} subEvents={subEvents}
            onClose={() => setShowRequestModal(false)}
            onDone={() => { setShowRequestModal(false); fetchCertificates(); showToast('✅ Request submitted!'); }} />
        )}
      </AnimatePresence>

      {toast && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-6 py-3 rounded-2xl text-sm font-semibold shadow-xl z-[200]">
          {toast}
        </div>
      )}
    </div>
  );
}
